CREATE TABLE IF NOT EXISTS platform_settings (key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS coupons (id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,discount_type TEXT NOT NULL,discount_value INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1,starts_at TEXT,ends_at TEXT);
CREATE TABLE IF NOT EXISTS refund_requests (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),customer_id TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested',admin_note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE users ADD COLUMN rider_available INTEGER NOT NULL DEFAULT 0;